import { component$, $ } from '@builder.io/qwik';
import { GrafloriaDashboard } from '@grafloria/qwik';
import type { DashboardViewSpec } from '@grafloria/element';
import { markReady } from '../ready';

// NESTED CONTAINERS. A widget with `widgets` of its own is a CONTAINER: it
// mounts as a locked slab in the board with its own pack grid inside (here
// 4 columns for 3 KPIs, so a dragged-in tile has a free slot to land in).
// width + height in options → mode 'fixed': a 1180×620 design the camera fits
// into the element.
const options = { columns: 12, gap: 8, width: 1180, height: 620 };
const views: DashboardViewSpec[] = [{
  id: 'main', name: 'Overview',
  widgets: [
    { id: 'trend', kind: 'line', span: 8, rows: 2, title: 'Revenue trend',
      data: { series: [{ name: 'Revenue', values: [1.2, 1.5, 1.4, 1.9, 2.3, 2.8] }], labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'] } },
    { id: 'mix', kind: 'donut', span: 4, rows: 2, title: 'By region',
      data: { slices: [{ label: 'EMEA', value: 2.9, color: '#3B52D9' }, { label: 'APAC', value: 1.8, color: '#0891b2' }, { label: 'NA', value: 2.1, color: '#f59e0b' }] } },
    // The section's header is the kit's `caption` (as on the JS page): a band
    // with a subtitle and an ⓘ, reserved inside the frame.
    { id: 'kpis', title: 'KPI section', caption: { subtitle: 'three KPIs in a 4-column section', description: 'Drag a tile across the edge: the section adopts it' }, span: 12, rows: 1, columns: 4,
      widgets: [
        { id: 'k-rev',  kind: 'kpi', span: 1, rows: 1, data: { label: 'Revenue',   value: '$6.8M', delta: 12.4 } },
        { id: 'k-cust', kind: 'kpi', span: 1, rows: 1, data: { label: 'Customers', value: '1,284', delta: 8.1 } },
        { id: 'k-win',  kind: 'kpi', span: 1, rows: 1, data: { label: 'Win rate',  value: '27.4%', delta: 3.5 } },
      ] },
    { id: 'deals', kind: 'bar', span: 12, rows: 2, title: 'Deals by quarter',
      data: { bars: [{ label: 'Q1', value: 210 }, { label: 'Q2', value: 262 }, { label: 'Q3', value: 244 }, { label: 'Q4', value: 301 }] } },
  ],
}];

export default component$(() => (
  <div style={{ height: '100vh' }}>
    <GrafloriaDashboard views={views} options={options} onReady$={$(() => markReady())} />
  </div>
));

collab/two-tabs-live.text:
import { component$, noSerialize, useSignal } from '@builder.io/qwik';
import { GrafloriaFlow, type GrafloriaCollabOptions } from '@grafloria/qwik';
import { BroadcastChannelTransport } from '@grafloria/engine';
import { markReady } from '../ready';

const nodesA = [
  { id: 'a', position: { x: 60, y: 60 },  size: { width: 150, height: 66 }, data: { label: 'Ingest' } },
  { id: 'b', position: { x: 320, y: 60 }, size: { width: 150, height: 66 }, data: { label: 'Publish' } },
];
const edgesA = [{ id: 'e1', source: 'a', target: 'b' }];

/** Both peers' collab options. A transport holds a live channel and callbacks —
 *  not data — so each options object goes through noSerialize(). */
function makeCollab() {
  const room = 'qwik-collab-' + Math.random().toString(36).slice(2, 8);
  const a: GrafloriaCollabOptions = { transport: new BroadcastChannelTransport({ name: room, actor: 'ana' }), actor: 'ana', presence: { name: 'Ana' } };
  const b: GrafloriaCollabOptions = { transport: new BroadcastChannelTransport({ name: room, actor: 'ben' }), actor: 'ben', presence: { name: 'Ben' } };
  return { collabA: noSerialize(a), collabB: noSerialize(b) };
}

/** Real multiplayer with no server: two canvases in one page, each joined to
 *  the same room over BroadcastChannel via collab. Drag a node on the left —
 *  the right converges through the engine's per-property CRDT, with presence
 *  cursors painted for the remote actor. */
export default component$(() => {
  // The initializer runs once per component — one room for the page's life.
  const collab = useSignal(makeCollab);
  return (
    <div style={{ display: 'flex', height: '100vh', gap: '1px', background: '#E3E7F2' }}>
      <div style={{ flex: '1', background: '#fff', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '6px 12px', fontSize: '12px', color: '#5A6478' }}>Tab A — Ana</div>
        <GrafloriaFlow defaultNodes={nodesA} defaultEdges={edgesA} collab={collab.value.collabA} style={{ flex: '1' }}
          onInit$={() => markReady()} />
      </div>
      <div style={{ flex: '1', background: '#fff', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '6px 12px', fontSize: '12px', color: '#5A6478' }}>Tab B — Ben</div>
        <GrafloriaFlow defaultNodes={structuredClone(nodesA)} defaultEdges={structuredClone(edgesA)} collab={collab.value.collabB} style={{ flex: '1' }} />
      </div>
    </div>
  );
});

collab/comments.text:
import { component$, $, noSerialize, useSignal, type NoSerialize } from '@builder.io/qwik';
import { GrafloriaFlow, GrafloriaCommentPanel, type DiagramInstance } from '@grafloria/qwik';
import type { CommentStore } from '@grafloria/engine';
import { markReady } from '../ready';

const nodes = [
  { id: 'design', position: { x: 80, y: 120 },  size: { width: 150, height: 66 }, data: { label: 'Design' } },
  { id: 'review', position: { x: 330, y: 120 }, size: { width: 150, height: 66 }, data: { label: 'Review' } },
  { id: 'ship',   position: { x: 580, y: 120 }, size: { width: 150, height: 66 }, data: { label: 'Ship' } },
];
const edges = [
  { id: 'e1', source: 'design', target: 'review' },
  { id: 'e2', source: 'review', target: 'ship' },
];

/** Resolve once the comment panel has mounted inside `root` — it subscribes to
 *  the store in the same tick it mounts. Gives up after ~2 s rather than hang. */
function panelBound(root: HTMLElement | undefined): Promise<void> {
  return new Promise((resolve) => {
    let frames = 0;
    const poll = () => {
      if (root?.querySelector('[data-grafloria-comment-panel]') || ++frames > 120) resolve();
      else requestAnimationFrame(poll);
    };
    poll();
  });
}

/** Anchored comment threads: comments turns the capability on; the
 *  conversation panel binds to the canvas's own CommentStore.
 *
 *  The thread is seeded AFTER the panel binds: the panel paints on store
 *  changes, so a thread created before it mounted would only appear on the
 *  next change. */
export default component$(() => {
  const root = useSignal<HTMLDivElement>();
  // The store is a live object with subscribers — noSerialize keeps it out of state.
  const store = useSignal<NoSerialize<CommentStore>>();
  return (
    <div ref={root} style={{ display: 'flex', height: '100vh' }}>
      <GrafloriaFlow
        defaultNodes={nodes}
        defaultEdges={edges}
        comments
        style={{ flex: '1' }}
        onInit$={$(async (instance: DiagramInstance) => {
          const s = instance.getCommentStore();
          if (s) {
            store.value = noSerialize(s);
            await panelBound(root.value);
            const t = s.createThread({ kind: 'node', id: 'review' }, 'Can we tighten the hero copy?');
            s.reply(t, 'On it — draft by Friday.');
          }
          markReady();
        })}
      />
      {store.value && (
        <div style={{ width: '300px', borderLeft: '1px solid #E3E7F2', overflow: 'auto' }}>
          <GrafloriaCommentPanel store={store.value} />
        </div>
      )}
    </div>
  );
});

