  noop: () => ({ amount: 10, unit: 'seconds' }),
  notify: () => ({ channel: '#it-ops', text: 'Quality run finished: {{ $json.verdict }}' }),
};
// Simulated per-node execution time (ms) — DETERMINISTIC.
export const SIM_MS: Record<string, number> = {
