      diagram.addGroup(g1);
      diagram.addGroup(g2);
      g1.padding = 12;
      g2.padding = 12;
      g1.addMember('m1a', diagram);
      g1.addMember('m1b', diagram);
      g2.addMember('m2a', diagram);
      g2.addMember('m2b', diagram);
      await engine.layout('dagre', { direction: 'LR', nodeSpacing: 30, rankSpacing: 60 });
